#include <iostream>
#include <cmath>
#include <vector>
#include <string>
#include <algorithm>
#include <cstdint>

using namespace std;

int weight;
int itemMass;
vector<bool> arr(100, false);

class Main {
public:
    bool isBalanced() {
        bool isBalance = false;
        int64_t pod1 = itemMass, pod2 = 0;
        while (true) {
            if (pod1 > pod2) {
                int64_t nextMass = getMass(pod1 - pod2);
                if (nextMass != 0) {
                    pod2 += nextMass;
                } else {
                    break;
                }
            } else if (pod1 < pod2) {
                int64_t nextMass = getMass(pod2 - pod1);
                if (nextMass != 0) {
                    pod1 += nextMass;
                } else {
                    break;
                }
            } else {
                isBalance = true;
                break;
            }
        }
        return isBalance;
    }

    int64_t getMass(int64_t mass) {
        int64_t result = 0;
        int logBase = 0;
        if (mass > 0 && weight > 1) {
            logBase = (int)(log((double)mass) / log((double)weight));
        }
        // To handle cases where mass is 0 or 1, or weight is 1
        if (mass == 0) {
            return 0;
        }
        // Compute sumTotal
        // To avoid floating point inaccuracies, compute logBase carefully
        // and handle edge cases
        int64_t sumTotal = 0;
        if (logBase >= 0) {
            // Compute bi = (weight^(logBase+1) - 1) / (weight - 1)
            // Use pow for exponentiation
            // For large exponents, pow may be imprecise, but for this problem, acceptable
            int64_t pow_weight_logplus1 = (int64_t)pow(weight, logBase + 1);
            sumTotal = (pow_weight_logplus1 - 1) / (weight - 1);
        }

        if (mass > sumTotal && !arr[logBase + 1]) {
            result = (int64_t)pow(weight, logBase + 1);
            arr[logBase + 1] = true;
        } else if (mass <= sumTotal && !arr[logBase]) {
            result = (int64_t)pow(weight, logBase);
            arr[logBase] = true;
        } else {
            result = 0;
        }
        return result;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> weight >> itemMass;
    Main wb;
    if (wb.isBalanced())
        cout << "YES\n";
    else
        cout << "NO\n";
    return 0;
}

